#!/usr/bin/env node

import { FastMCP } from 'fastmcp';
import { Pool } from 'pg';
import config, { dbConfig } from './config.js';
import Logger from './utils/logger.js';
import { CoreTools } from './tools/coreTools.js';

console.log = (...args: any[]) => {
  Logger.info('[STDOUT REDIRECT]', ...args);
};

const server = new FastMCP({
  name: 'postgresql-mcp-server',
  version: '1.0.0',
});

let pool: Pool | null = null;

const globalState = {
  isConnected: false,
  connectionInfo: null as any,
  lastError: null as string | null,
  connectionCount: 0,
};

function getPool(): Pool {
  if (!pool) {
    pool = new Pool(config.database);
    pool.on('connect', () => {
      Logger.info('≡ƒöù Nouvelle connexion PostgreSQL ├⌐tablie');
      globalState.connectionCount++;
      updateGlobalState(true);
    });
    pool.on('error', (err) => {
      Logger.error('Γ¥î Erreur du pool PostgreSQL:', err);
      updateGlobalState(false, err.message);
    });
    pool.on('remove', () => {
      globalState.connectionCount--;
      Logger.debug(`≡ƒôñ Connexion retir├⌐e du pool. Total: ${globalState.connectionCount}`);
    });
  }
  return pool;
}

function updateGlobalState(connected: boolean, error?: string) {
  globalState.isConnected = connected;
  globalState.lastError = error || null;
  if (connected && pool) {
    globalState.connectionInfo = {
      host: config.database.connectionString?.split('@')[1]?.split('/')[0] || 'localhost',
      database: dbConfig.POSTGRES_DATABASE,
      activeConnections: globalState.connectionCount,
      maxConnections: config.database.max,
      sslEnabled: config.database.ssl !== false,
    };
  }
}

// Enregistrer les outils Core (refactorisation : 38 outils ΓåÆ 8 outils coh├⌐rents)
const coreTools = new CoreTools(getPool(), server);
coreTools.registerTools();

async function cleanup() {
  Logger.info('≡ƒº╣ Nettoyage du serveur PostgreSQL MCP...');
  try {
    if (pool) {
      await pool.end();
      pool = null;
    }
    Logger.info('Γ£à Nettoyage termin├⌐');
  } catch (error) {
    Logger.error('Γ¥î Erreur lors du nettoyage:', error);
  }
}

process.on('SIGINT', async () => {
  await cleanup();
  process.exit(0);
});

process.on('SIGTERM', async () => {
  await cleanup();
  process.exit(0);
});

process.on('uncaughtException', error => {
  Logger.error('Γ¥î Erreur non captur├⌐e:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  Logger.error('Γ¥î Promesse rejet├⌐e non g├⌐r├⌐e:', reason);
  process.exit(1);
});

async function main() {
  Logger.info('≡ƒÜÇ D├⌐marrage PostgreSQL MCP Server v1.0.0...\n');
  try {
    const testPool = getPool();
    const client = await testPool.connect();
    await client.query('SELECT 1');
    await client.release();
    updateGlobalState(true);
    Logger.info('Γ£à Connexion PostgreSQL ├⌐tablie\n');
    await server.start();
    Logger.info('Γ£à Serveur MCP d├⌐marr├⌐\n');
    Logger.info('≡ƒôè Serveur PostgreSQL MCP pr├¬t:');
    Logger.info(`   ΓÇó Base: ${dbConfig.POSTGRES_DATABASE}`);
    Logger.info(`   ΓÇó H├┤te: ${dbConfig.POSTGRES_HOST}:${dbConfig.POSTGRES_PORT}`);
    Logger.info(`   ΓÇó SSL: ${config.database.ssl !== false ? 'Activ├⌐' : 'D├⌐sactiv├⌐'}`);
    Logger.info(`   ΓÇó Outils: 8 (Core Tools)`);
  } catch (error: any) {
    const isConnectionError = error.code === 'ECONNREFUSED' ||
                              error.code === 'ENOTFOUND' ||
                              error.code === 'ECONNRESET' ||
                              error.message?.includes('connect ECONNREFUSED') ||
                              error.message?.includes('connect ENOTFOUND');
    if (isConnectionError) {
      Logger.error('Γ¥î Impossible de se connecter ├á PostgreSQL');
      Logger.error('');
      Logger.error('≡ƒöì Probl├¿me d├⌐tect├⌐: La base de donn├⌐es PostgreSQL n\'est pas accessible');
      Logger.error('');
      Logger.error('≡ƒôï Solutions possibles:');
      Logger.error('   1. D├⌐marrer PostgreSQL:');
      if (process.platform === 'win32') {
        Logger.error('      pg_ctl -D "C:\\Program Files\\PostgreSQL\\XX\\data" start');
      } else {
        Logger.error('      sudo service postgresql start');
        Logger.error('      ou: sudo systemctl start postgresql');
      }
      Logger.error('');
      Logger.error('   2. V├⌐rifier la configuration dans .env:');
      Logger.error(`      ΓÇó H├┤te: ${dbConfig.POSTGRES_HOST}:${dbConfig.POSTGRES_PORT}`);
      Logger.error(`      ΓÇó Base: ${dbConfig.POSTGRES_DATABASE}`);
      Logger.error(`      ΓÇó Utilisateur: ${dbConfig.POSTGRES_USER}`);
      Logger.error('');
      Logger.error('   3. D├⌐marrer avec Docker:');
      Logger.error('      docker run --name postgres-mcp -e POSTGRES_PASSWORD=9022 \\');
      Logger.error('        -e POSTGRES_USER=postgres -e POSTGRES_DB=financial_analyst \\');
      Logger.error('        -p 5432:5432 -d postgres:15');
      Logger.error('');
      Logger.error('≡ƒÆí Erreur technique:', error.code || error.message);
    } else {
      Logger.error('Γ¥î Erreur fatal:', error);
    }
    await cleanup();
    process.exit(1);
  }
}
main();

import { Pool } from 'pg';
import { embeddingService } from '../services/embeddingService.js';
import config, { dbConfig } from '../config.js';
import Logger from '../utils/logger.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

// Setup Env
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.resolve(__dirname, '../../.env') });

async function backfillEmbeddings() {
    Logger.info("≡ƒÜÇ Starting Embedding Backfill Process...");

    // 1. Setup DB Connection
    const pool = new Pool(config.database);
    
    try {
        // 2. Count Targets (Recent News - last 7 days)
        // Optimized to prioritize recent news first
        const daysToLookBack = 7; 
        const countQuery = `
            SELECT COUNT(*) 
            FROM enhanced_news 
            WHERE embedding IS NULL 
            AND timestamp_unix_ms > (EXTRACT(EPOCH FROM NOW()) * 1000 - ${daysToLookBack * 24 * 60 * 60 * 1000})
        `;
        const resCount = await pool.query(countQuery);
        const totalToProcess = parseInt(resCount.rows[0].count);

        Logger.info(`≡ƒÄ» Found ${totalToProcess} recent articles (last ${daysToLookBack} days) needing embeddings.`);

        if (totalToProcess === 0) {
            Logger.info("Γ£à No articles to process.");
            return;
        }

        // 3. AUTO-DETECT & MIGRATE DIMENSIONS
        // Generate one probe vector to check dimensions
        Logger.info("≡ƒò╡∩╕Å Probing API for vector dimensions...");
        const probeVector = await embeddingService.generateEmbedding("Probe", { model: 'qwen/qwen3-embedding-8b' });
        const apiDims = probeVector.length;
        Logger.info(`≡ƒôÅ API Model 'qwen/qwen3-embedding-8b' returns ${apiDims} dimensions.`);

        // Check DB Column Type
        const schemaRes = await pool.query(`
            SELECT atttypmod 
            FROM pg_attribute 
            WHERE attrelid = 'enhanced_news'::regclass 
            AND attname = 'embedding'
        `);
        const dbDims = schemaRes.rows[0]?.atttypmod; // vector typmod is usually dims
        
        // Note: pg_vector typmod needs parsing or just try/catch the insert. 
        // Simpler: Just try to ALTER if catch error implies mismatch? 
        // Better: Always ensure correct type.
        
        // Let's blindly run ALTER if we can, or just log.
        // If apiDims (e.g. 4096) != 1536 (default), execution will fail.
        
        if (apiDims !== 1536) { // Assuming 1536 is the old default
             Logger.warn(`ΓÜá∩╕Å Dimension Mismatch! API: ${apiDims} vs DB Default (1536). Initiating Migration...`);
             try {
                 await pool.query(`ALTER TABLE enhanced_news ALTER COLUMN embedding TYPE vector(${apiDims})`);
                 Logger.info(`Γ£à Schema Updated: embedding column is now vector(${apiDims})`);
             } catch (e: any) {
                 Logger.error(`Γ¥î Migration Failed: ${e.message}. Attempting to proceed anyway...`);
             }
        }

        // 4. Process in Batches
        const BATCH_SIZE = 10;
        let processed = 0;
        let errors = 0;

        // Cursor logic or simple offset
        // Using cursor-like approach by selecting NULLs each time is robust but order matters
        const selectQuery = `
            SELECT id, title, content 
            FROM enhanced_news 
            WHERE embedding IS NULL 
            AND timestamp_unix_ms > (EXTRACT(EPOCH FROM NOW()) * 1000 - ${daysToLookBack * 24 * 60 * 60 * 1000})
            ORDER BY timestamp_unix_ms DESC
            LIMIT ${BATCH_SIZE}
        `;

        while (processed < totalToProcess) {
            const rows = (await pool.query(selectQuery)).rows;
            if (rows.length === 0) break;

            Logger.info(`≡ƒôª Processing batch of ${rows.length} articles...`);

            // Parallel Processing within Batch
            await Promise.all(rows.map(async (row) => {
                try {
                    const textToEmbed = `${row.title}\n\n${row.content || ''}`.substring(0, 8000); // Truncate safety
                    
                    // Generate Vector (Qwen via OpenRouter)
                    const vector = await embeddingService.generateEmbedding(textToEmbed, {
                        model: 'qwen/qwen3-embedding-8b',
                        dimensions: 1536 // Or let API decide, but usually standard fixed
                    });

                    // Update DB - Using explicit casting for pgvector
                    // Note: pgvector expects '[...]' string format
                    const vectorStr = `[${vector.join(',')}]`;
                    
                    await pool.query(
                        `UPDATE enhanced_news SET embedding = $1::vector WHERE id = $2`,
                        [vectorStr, row.id]
                    );
                    
                    process.stdout.write('.'); // Progress dot
                } catch (err: any) {
                    process.stdout.write('x');
                    errors++;
                    Logger.error(`Failed ID ${row.id}: ${err.message}`);
                }
            }));
            
            processed += rows.length;
            console.log(`\n≡ƒôè Progress: ${processed}/${totalToProcess} (Errors: ${errors})`);
            
            // Rate Limit Safety (optional but good practice)
            await new Promise(r => setTimeout(r, 1000));
        }

        Logger.info("Γ£à Backfill Complete!");

    } catch (err) {
        Logger.error("Γ¥î Fatal Script Error", err);
    } finally {
        await pool.end();
    }
}

backfillEmbeddings();

import axios from 'axios';
import Logger from '../utils/logger.js';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

// Gestion __dirname pour ESM
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Charger .env explicitement pour ├¬tre s├╗r
dotenv.config({ path: path.resolve(__dirname, '../../.env') });

/**
 * Service de g├⌐n├⌐ration d'embeddings pour production
 * Supporte OpenAI/OpenRouter API
 */
export class EmbeddingService {
  private apiKey: string | null = null;
  private baseURL: string = 'https://openrouter.ai/api/v1';
  private modelName: string = 'qwen/qwen3-embedding-8b'; 
  
  private cache: Map<string, number[]> = new Map();
  private maxCacheSize = 1000;

  constructor() {
    // Debug Paths and Env
    Logger.debug(`≡ƒôé CWD: ${process.cwd()}`);
    Logger.debug(`≡ƒôé Service Dir: ${__dirname}`);
    
    // Initialiser OpenRouter API si cl├⌐ disponible
    const openRouterKey = process.env.OPEN_ROUTER_API_KEY || process.env.OPENROUTER_API_KEY;

    if (openRouterKey) {
      this.apiKey = openRouterKey;
      Logger.info(`Γ£à Embedding Service: OpenRouter API Configured (Key len: ${this.apiKey.length})`);
    } else if (process.env.OPENAI_API_KEY) {
        this.apiKey = process.env.OPENAI_API_KEY;
        this.baseURL = 'https://api.openai.com/v1';
        this.modelName = 'text-embedding-3-small';
        Logger.info('Γ£à Embedding Service: OpenAI API Configured (Fallback)');
    } else {
      const allKeys = Object.keys(process.env).filter(k => k.includes('API'));
      Logger.warn(`ΓÜá∩╕Å Embedding Service: NO API KEY - MOCK MODE ACTIVE. Keys found: ${allKeys.join(', ')}`);
    }
  }

  /**
   * G├⌐n├¿re un embedding ├á partir d'un texte
   * @param text - Texte ├á transformer en vecteur
   * @param options - Options de g├⌐n├⌐ration
   * @returns Promise<number[]>
   */
  async generateEmbedding(
    text: string,
    options: {
      model?: string;
      useCache?: boolean;
      dimensions?: number;
    } = {}
  ): Promise<number[]> {
    const {
      model = this.modelName,
      useCache = true,
      dimensions = 1536 
    } = options;

    // 0. Nettoyer
    const normalizedText = text.trim();
    if (!normalizedText) return new Array(dimensions).fill(0);

    // 1. Cache Check
    const cacheKey = `${model}:${normalizedText}`;
    if (useCache && this.cache.has(cacheKey)) {
      Logger.debug(`≡ƒôª Embedding Cache Hit`);
      return this.cache.get(cacheKey)!;
    }

    try {
      if (this.apiKey) {
          // REAL API CALL
          const embedding = await this.generateWithAPI(normalizedText, model);
          
          // Cache
          if (useCache) this.addToCache(cacheKey, embedding);
          return embedding;
      } else {
          throw new Error("Γ¥î CRITICAL: No API Configuration found. Mock mode is disabled. Please set OPEN_ROUTER_API_KEY in .env");
      }

    } catch (error: any) {
      Logger.error(`Γ¥î Embedding Gen Failed: ${error.message}`);
      throw error; 
    }
  }

  /**
   * Appelle l'API OpenRouter/OpenAI pour g├⌐n├⌐rer l'embedding
   */
  private async generateWithAPI(text: string, model: string): Promise<number[]> {
      try {
        const response = await axios.post(
            `${this.baseURL}/embeddings`,
            {
                model: model,
                input: text,
                encoding_format: "float"
            },
            {
                headers: {
                    'Authorization': `Bearer ${this.apiKey}`,
                    'Content-Type': 'application/json',
                    // OpenRouter specific headers
                    'HTTP-Referer': 'https://sentinel-bot.local', 
                    'X-Title': 'Sentinel Market AI'
                },
                timeout: 15000 // Increased timeout for Qwen
            }
        );

        if (response.data && response.data.data && response.data.data.length > 0) {
            const vec = response.data.data[0].embedding;
            Logger.debug(`Γ£à API Embedding: ${vec.length} dims (Model: ${model})`);
            return vec;
        } else {
            throw new Error('Invalid API Response format: No embedding data found');
        }
      } catch (err: any) {
          const msg = err.response?.data?.error?.message || err.message;
          Logger.error(`API Error details: ${JSON.stringify(err.response?.data || {})}`);
          throw new Error(`API Error: ${msg}`);
      }
  }

  // Disabled Mock Embedding
  // private generateMockEmbedding(dimensions: number): number[] { ... }

  private addToCache(key: string, embedding: number[]): void {
    if (this.cache.size >= this.maxCacheSize) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) this.cache.delete(firstKey);
    }
    this.cache.set(key, embedding);
  }

  clearCache(): void {
    this.cache.clear();
    Logger.info('≡ƒº╣ Cache vid├⌐');
  }

  async benchmark(texts: string[]): Promise<any> {
     // ... (Benchmark kept simple)
     return { averageTime: 0, totalTime: 0, successRate: 0 }; 
  }
}

export const embeddingService = new EmbeddingService();

#!/usr/bin/env node

import { Pool } from 'pg';
import Logger from '../utils/logger.js';
import { embeddingService } from './embeddingService.js';

/**
 * Service de recherche hybride (Full-text + Vecteur)
 * Combine la rapidit├⌐ du full-text avec la pr├⌐cision du vecteur
 */
export class HybridSearchService {
  private pool: Pool;

  constructor(pool: Pool) {
    this.pool = pool;
  }

  /**
   * Recherche hybride intelligente
   * @param query - Requ├¬te utilisateur
   * @param options - Options de recherche
   * @returns R├⌐sultats class├⌐s par pertinence
   */
  async search(
    query: string,
    options: {
      tableName: string;
      vectorColumn?: string;
      contentColumn?: string;
      topK?: number;
      textLimit?: number;
      hybridMode?: boolean;
      useCache?: boolean;
    }
  ): Promise<{
    results: any[];
    metadata: {
      query: string;
      mode: 'hybrid' | 'vector' | 'text';
      executionTime: number;
      totalResults: number;
      embeddingTime?: number;
      textSearchTime?: number;
      vectorSearchTime?: number;
    };
  }> {
    const {
      tableName,
      vectorColumn = 'embedding',
      contentColumn = 'content',
      topK = 10,
      textLimit = 100,
      hybridMode = true,
      useCache = true
    } = options;

    const startTime = Date.now();
    let results: any[] = [];
    let metadata: any = {
      query,
      mode: 'hybrid' as const,
      executionTime: 0,
      totalResults: 0
    };

    try {
      if (hybridMode) {
        // MODE HYBRIDE: Full-text + Vecteur
        const hybridResults = await this.performHybridSearch(
          query,
          tableName,
          vectorColumn,
          contentColumn,
          topK,
          textLimit,
          useCache
        );

        results = hybridResults.results;
        metadata = { ...metadata, ...hybridResults.metadata, mode: 'hybrid' };
      } else {
        // MODE VECTEUR SEUL
        const vectorResults = await this.performVectorSearch(
          query,
          tableName,
          vectorColumn,
          topK,
          useCache
        );

        results = vectorResults.results;
        metadata = { ...metadata, ...vectorResults.metadata, mode: 'vector' };
      }

      metadata.executionTime = Date.now() - startTime;
      metadata.totalResults = results.length;

      Logger.info(`Γ£à Recherche termin├⌐e (${metadata.mode}): ${results.length} r├⌐sultats en ${metadata.executionTime}ms`);

      return {
        results,
        metadata
      };

    } catch (error: any) {
      Logger.error('Γ¥î Erreur recherche hybride:', error.message);
      throw new Error(`├ëchec de recherche: ${error.message}`);
    }
  }

  /**
   * Recherche hybride: Full-text puis vecteur
   */
  private async performHybridSearch(
    query: string,
    tableName: string,
    vectorColumn: string,
    contentColumn: string,
    topK: number,
    textLimit: number,
    useCache: boolean
  ): Promise<{ results: any[]; metadata: any }> {
    const startTime = Date.now();
    const client = await this.pool.connect();

    try {
      // ├ëTAPE 1: Recherche full-text (filtrage rapide)
      Logger.debug('≡ƒöì ├ëtape 1: Recherche full-text...');
      const textStartTime = Date.now();

      const textResults = await client.query(
        `
        SELECT id, ${contentColumn} as content,
               ts_rank(to_tsvector('french', ${contentColumn}),
                       plainto_tsquery('french', $1)) as text_rank
        FROM ${tableName}
        WHERE to_tsvector('french', ${contentColumn}) @@ plainto_tsquery('french', $1)
        ORDER BY text_rank DESC
        LIMIT $2
        `,
        [query, textLimit]
      );

      const textSearchTime = Date.now() - textStartTime;
      Logger.debug(`Γ£à Full-text: ${textResults.rows.length} r├⌐sultats en ${textSearchTime}ms`);

      if (textResults.rows.length === 0) {
        return {
          results: [],
          metadata: {
            textSearchTime,
            vectorSearchTime: 0,
            embeddingTime: 0,
            textResultsCount: 0
          }
        };
      }

      // ├ëTAPE 2: G├⌐n├⌐ration d'embedding de la requ├¬te
      Logger.debug('≡ƒºá ├ëtape 2: G├⌐n├⌐ration embedding...');
      const embeddingStartTime = Date.now();
      const queryVector = await embeddingService.generateEmbedding(query, { useCache });
      const embeddingTime = Date.now() - embeddingStartTime;
      Logger.debug(`Γ£à Embedding: ${embeddingTime}ms`);

      // ├ëTAPE 3: Recherche vectorielle dans les r├⌐sultats filtr├⌐s
      Logger.debug('≡ƒÄ» ├ëtape 3: Recherche vectorielle...');
      const vectorStartTime = Date.now();

      const ids = textResults.rows.map((row: any) => row.id);
      
      // Adaptation dynamique pour UUID ou Integer
      // Si enhanced_news (UUID), on cast le VALUES en UUID
      // Si autre table (Integer), on cast en Integer ou laisse par d├⌐faut
      const isUUID = tableName === 'enhanced_news';
      const idType = isUUID ? '::uuid' : '';
      
      // Construction de la clause VALUES pour le JOIN
      // Ex: ($2::uuid, 1), ($3::uuid, 2)...
      const valuesClause = ids.map((id: any, index: number) => `($${index + 2}${idType}, ${index + 1})`).join(', ');

      const vectorQuery = `
        SELECT
          d.*,
          1 - (d.${vectorColumn} <=> $1::vector) as similarity,
          t.rank as text_rank_index
        FROM ${tableName} d
        JOIN (
          VALUES ${valuesClause}
        ) AS t(id, rank) ON d.id = t.id
        ORDER BY d.${vectorColumn} <=> $1::vector
        LIMIT $${ids.length + 2}
      `;

      const vectorResults = await client.query(vectorQuery, [
        `[${queryVector.join(',')}]`,
        ...ids,
        topK
      ]);

      const vectorSearchTime = Date.now() - vectorStartTime;
      Logger.debug(`Γ£à Vecteur: ${vectorResults.rows.length} r├⌐sultats en ${vectorSearchTime}ms`);

      // ├ëTAPE 4: Fusion et classement
      const mergedResults = vectorResults.rows.map((row: any, index: number) => {
          // Score texte approximatif bas├⌐ sur le rang (1er = 1.0, 2├¿me = 0.9...)
          const textScore = 1.0 / (row.text_rank_index || 100); 
          
          return {
            ...row,
            rank: index + 1,
            final_score: (row.similarity * 0.7) + (textScore * 0.3), // Score hybride
          };
      });

      // Trier par score final
      mergedResults.sort((a: any, b: any) => b.final_score - a.final_score);

      return {
        results: mergedResults,
        metadata: {
          textSearchTime,
          embeddingTime,
          vectorSearchTime,
          textResultsCount: textResults.rows.length,
          vectorResultsCount: vectorResults.rows.length
        }
      };

    } finally {
      client.release();
    }
  }

  /**
   * Recherche vecteur seule
   */
  private async performVectorSearch(
    query: string,
    tableName: string,
    vectorColumn: string,
    topK: number,
    useCache: boolean
  ): Promise<{ results: any[]; metadata: any }> {
    const startTime = Date.now();
    const client = await this.pool.connect();

    try {
      // G├⌐n├⌐rer l'embedding
      const embeddingStartTime = Date.now();
      const queryVector = await embeddingService.generateEmbedding(query, { useCache });
      const embeddingTime = Date.now() - embeddingStartTime;

      // Recherche vectorielle
      const vectorStartTime = Date.now();
      const results = await client.query(
        `
        SELECT *, 1 - (${vectorColumn} <=> $1::vector) as similarity
        FROM ${tableName}
        ORDER BY ${vectorColumn} <=> $1::vector
        LIMIT $2
        `,
        [`[${queryVector.join(',')}]`, topK]
      );

      const vectorSearchTime = Date.now() - vectorStartTime;

      return {
        results: results.rows,
        metadata: {
          embeddingTime,
          vectorSearchTime
        }
      };

    } finally {
      client.release();
    }
  }

  /**
   * Recherche full-text simple (sans vecteur)
   */
  async textSearch(
    query: string,
    tableName: string,
    contentColumn: string = 'content',
    topK: number = 10
  ): Promise<{ results: any[]; metadata: any }> {
    const startTime = Date.now();
    const client = await this.pool.connect();

    try {
      const results = await client.query(
        `
        SELECT *,
               ts_rank(to_tsvector('french', ${contentColumn}),
                       plainto_tsquery('french', $1)) as rank
        FROM ${tableName}
        WHERE to_tsvector('french', ${contentColumn}) @@ plainto_tsquery('french', $1)
        ORDER BY rank DESC
        LIMIT $2
        `,
        [query, topK]
      );

      return {
        results: results.rows,
        metadata: {
          executionTime: Date.now() - startTime,
          totalResults: results.rows.length
        }
      };

    } finally {
      client.release();
    }
  }

  /**
   * Suggestions de requ├¬tes (auto-compl├⌐tion)
   */
  async getSuggestions(
    partialQuery: string,
    tableName: string,
    contentColumn: string = 'content',
    limit: number = 5
  ): Promise<string[]> {
    const client = await this.pool.connect();

    try {
      const results = await client.query(
        `
        SELECT DISTINCT ${contentColumn}
        FROM ${tableName}
        WHERE ${contentColumn} ILIKE $1
        LIMIT $2
        `,
        [`%${partialQuery}%`, limit]
      );

      return results.rows.map((row: any) => row[contentColumn]);

    } finally {
      client.release();
    }
  }
}

#!/usr/bin/env node

import { Pool } from 'pg';
import Logger from '../utils/logger.js';
import { embeddingService } from './embeddingService.js';
import { HybridSearchService } from './hybridSearchService.js';

/**
 * Service de recherche intelligent
 * D├⌐tecte automatiquement le mode optimal et route les requ├¬tes
 */
export class IntelligentSearchService {
  private pool: Pool;
  private hybridSearch: HybridSearchService;

  constructor(pool: Pool) {
    this.pool = pool;
    this.hybridSearch = new HybridSearchService(pool);
  }

  /**
   * Point d'entr├⌐e principal - Recherche intelligente
   */
  async search(
    query: string,
    options: {
      tableName?: string;
      mode?: 'auto' | 'hybrid' | 'vector' | 'text';
      topK?: number;
      enableCache?: boolean;
    } = {}
  ): Promise<{
    results: any[];
    metadata: {
      query: string;
      detectedMode: string;
      actualMode: string;
      executionTime: number;
      embeddingGenerated: boolean;
      cacheHit: boolean;
    };
  }> {
    const {
      tableName = 'documents', // Valeur par d├⌐faut pour les tests
      mode = 'auto',
      topK = 10,
      enableCache = true
    } = options;

    const startTime = Date.now();

    try {
      // ├ëTAPE 1: D├⌐tecter le mode optimal
      const detectedMode = this.detectSearchMode(query, mode);
      Logger.debug(`≡ƒÄ» Mode d├⌐tect├⌐: ${detectedMode} pour: "${query.substring(0, 50)}..."`);

      // ├ëTAPE 2: Ex├⌐cuter la recherche selon le mode
      let results: any[] = [];
      let metadata: any = {
        query,
        detectedMode,
        actualMode: detectedMode,
        executionTime: 0,
        embeddingGenerated: false,
        cacheHit: false
      };

      switch (detectedMode) {
        case 'text':
          const textResult = await this.hybridSearch.textSearch(query, tableName, 'content', topK);
          results = textResult.results;
          metadata = { ...metadata, ...textResult.metadata };
          break;

        case 'vector':
          const vectorResult = await this.performVectorSearch(query, tableName, topK, enableCache);
          results = vectorResult.results;
          metadata = {
            ...metadata,
            ...vectorResult.metadata,
            embeddingGenerated: true,
            cacheHit: vectorResult.fromCache
          };
          break;

        case 'hybrid':
          const hybridResult = await this.hybridSearch.search(query, {
            tableName,
            topK,
            hybridMode: true,
            useCache: enableCache
          });
          results = hybridResult.results;
          metadata = {
            ...metadata,
            ...hybridResult.metadata,
            embeddingGenerated: true
          };
          break;

        default:
          throw new Error(`Mode non support├⌐: ${detectedMode}`);
      }

      metadata.executionTime = Date.now() - startTime;

      Logger.info(`Γ£à Recherche ${detectedMode} termin├⌐e: ${results.length} r├⌐sultats en ${metadata.executionTime}ms`);

      return {
        results,
        metadata
      };

    } catch (error: any) {
      Logger.error('Γ¥î Erreur recherche intelligente:', error.message);
      throw new Error(`├ëchec de recherche: ${error.message}`);
    }
  }

  /**
   * D├⌐tecte le mode optimal pour une requ├¬te
   */
  private detectSearchMode(userQuery: string, requestedMode: string): string {
    const query = userQuery.toLowerCase().trim();

    // Mode explicite demand├⌐
    if (requestedMode !== 'auto') {
      return requestedMode;
    }

    // Mots-cl├⌐s de test/debug - rediriger vers pgvector_search avec useRandomVector
    if (
      query.startsWith('test:') ||
      query.startsWith('debug:') ||
      query.startsWith('random:') ||
      query.includes('performance') ||
      query.includes('benchmark')
    ) {
      Logger.info('≡ƒÆí Utilisez pgvector_search avec useRandomVector: true pour les tests');
      return 'text'; // Mode par d├⌐faut pour les tests dans intelligent_search
    }

    // Requ├¬te tr├¿s courte - full-text suffisant
    if (query.split(' ').length <= 2) {
      return 'text';
    }

    // Requ├¬te complexe - hybride recommand├⌐
    if (
      query.includes('comment') ||
      query.includes('pourquoi') ||
      query.includes('quelle est') ||
      query.length > 50
    ) {
      return 'hybrid';
    }

    // Par d├⌐faut: vecteur
    return 'vector';
  }

  /**
   * Recherche avec vecteur al├⌐atoire
   */
  private async performRandomSearch(
    tableName: string,
    topK: number
  ): Promise<any[]> {
    const client = await this.pool.connect();

    try {
      // G├⌐n├⌐rer un vecteur al├⌐atoire 768D
      const randomVector = [];
      for (let i = 0; i < 768; i++) {
        randomVector.push((Math.random() * 2) - 1);
      }

      // Normaliser
      const magnitude = Math.sqrt(randomVector.reduce((sum, val) => sum + val * val, 0));
      const normalizedVector = randomVector.map(val => val / magnitude);

      // Recherche
      const results = await client.query(
        `
        SELECT *, 1 - (embedding <=> $1::vector) as similarity
        FROM ${tableName}
        ORDER BY embedding <=> $1::vector
        LIMIT $2
        `,
        [`[${normalizedVector.join(',')}]`, topK]
      );

      Logger.info('≡ƒÄ▓ Recherche al├⌐atoire effectu├⌐e');
      return results.rows;

    } finally {
      client.release();
    }
  }

  /**
   * Recherche vecteur seule
   */
  private async performVectorSearch(
    query: string,
    tableName: string,
    topK: number,
    useCache: boolean
  ): Promise<{ results: any[]; metadata: any; fromCache: boolean }> {
    const client = await this.pool.connect();

    try {
      // G├⌐n├⌐rer l'embedding
      const embedding = await embeddingService.generateEmbedding(query, { useCache });

      // V├⌐rifier si vient du cache
      const fromCache = false; // Note: Cette v├⌐rification pourrait ├¬tre am├⌐lior├⌐e avec un cache LRU

      // Recherche
      const results = await client.query(
        `
        SELECT *, 1 - (embedding <=> $1::vector) as similarity
        FROM ${tableName}
        ORDER BY embedding <=> $1::vector
        LIMIT $2
        `,
        [`[${embedding.join(',')}]`, topK]
      );

      return {
        results: results.rows,
        metadata: {
          embeddingDimensions: embedding.length,
          queryLength: query.length
        },
        fromCache
      };

    } finally {
      client.release();
    }
  }

  /**
   * Analyse et sugg├¿re des optimisations
   */
  async analyzeQuery(query: string): Promise<{
    mode: string;
    confidence: number;
    reasoning: string[];
    suggestions: string[];
  }> {
    const mode = this.detectSearchMode(query, 'auto');
    const reasoning: string[] = [];
    const suggestions: string[] = [];

    // Analyser la requ├¬te
    const words = query.split(' ').length;
    const length = query.length;

    if (words <= 2) {
      reasoning.push('Requ├¬te courte - full-text suffira');
      suggestions.push('Utilisez le mode "text" pour plus de rapidit├⌐');
    }

    if (query.includes('comment') || query.includes('pourquoi')) {
      reasoning.push('Question complexe - vecteur recommand├⌐');
      suggestions.push('Mode "hybrid" offrira les meilleurs r├⌐sultats');
    }

    if (query.startsWith('test:') || query.startsWith('debug:')) {
      reasoning.push('Requ├¬te de test d├⌐tect├⌐e');
      suggestions.push('Utilisez pgvector_search avec useRandomVector: true pour les tests');
    }

    if (length > 100) {
      reasoning.push('Requ├¬te longue - vecteur plus pr├⌐cis');
      suggestions.push('Mode "hybrid" pour combiner vitesse et pr├⌐cision');
    }

    // Calculer la confiance
    let confidence = 0.5;
    if (mode === 'text' && words <= 2) confidence = 0.8;
    if (mode === 'hybrid' && (query.includes('comment') || length > 50)) confidence = 0.9;
    if (mode === 'vector' && length > 20 && words > 2) confidence = 0.7;

    return {
      mode,
      confidence,
      reasoning,
      suggestions
    };
  }

  /**
   * Benchmark des diff├⌐rents modes
   */
  async benchmark(
    testQueries: string[],
    tableName: string,
    iterations: number = 3
  ): Promise<{
    text: { avgTime: number; successRate: number };
    vector: { avgTime: number; successRate: number };
    hybrid: { avgTime: number; successRate: number };
  }> {
    Logger.info(`≡ƒº¬ Benchmark sur ${testQueries.length} requ├¬tes (${iterations} it├⌐rations)...`);

    const modes = ['text', 'vector', 'hybrid'];
    const results: any = {};

    for (const mode of modes) {
      let totalTime = 0;
      let successCount = 0;

      for (let i = 0; i < iterations; i++) {
        for (const query of testQueries) {
          try {
            const start = Date.now();
            await this.search(query, { tableName, mode: mode as any });
            totalTime += Date.now() - start;
            successCount++;
          } catch (error) {
            Logger.error(`Γ¥î ├ëchec mode ${mode}: "${query}"`);
          }
        }
      }

      results[mode] = {
        avgTime: totalTime / (testQueries.length * iterations),
        successRate: (successCount / (testQueries.length * iterations)) * 100
      };

      Logger.info(`Γ£à ${mode}: ${results[mode].avgTime.toFixed(2)}ms avg, ${results[mode].successRate.toFixed(1)}% success`);
    }

    return results;
  }

  /**
   * Suggestions de requ├¬tes (d├⌐l├⌐gu├⌐ ├á HybridSearchService)
   */
  async getSuggestions(
    partialQuery: string,
    tableName: string,
    contentColumn: string = 'content',
    limit: number = 5
  ): Promise<string[]> {
    return this.hybridSearch.getSuggestions(partialQuery, tableName, contentColumn, limit);
  }
}

#!/usr/bin/env node

import { FastMCP } from 'fastmcp';
import { z } from 'zod';
import { Pool } from 'pg';
import Logger from '../utils/logger.js';
import { IntelligentSearchService } from '../services/intelligentSearchService.js';
import { embeddingService } from '../services/embeddingService.js';
import { DBOptimizer } from '../utils/dbOptimizer.js';

/**
 * Outils MCP Core - Refactorisation pour coh├⌐rence et simplicit├⌐
 *
 * 8 outils IMPLICITES et COH├ëRENTS au lieu de 38 dispers├⌐s
 */
export class CoreTools {
  private pool: Pool;
  private server: FastMCP;
  private searchService: IntelligentSearchService;
  private optimizer: DBOptimizer;

  constructor(pool: Pool, server: FastMCP) {
    this.pool = pool;
    this.server = server;
    this.searchService = new IntelligentSearchService(pool);
    this.optimizer = new DBOptimizer(pool);
  }

  registerTools(): void {
    this.diagnose();
    this.explore();
    this.query();
    this.search();
    this.insert();
    this.manageVectors();
    this.optimize();
    this.vectorize_row();
    this.help();

    Logger.info('Γ£à Outils Core enregistr├⌐s (8 outils coh├⌐rents)');
  }

  // ============================================================================
  // 1. DIAGNOSE - Diagnostic Complet
  // ============================================================================
  private diagnose(): void {
    this.server.addTool({
      name: 'diagnose',
      description: '≡ƒöì Diagnostic complet de la base de donn├⌐es avec solutions automatiques',
      parameters: z.object({
        type: z.enum(['connection', 'performance', 'all']).default('all').describe('Type de diagnostic'),
        deep: z.boolean().default(false).describe('Diagnostic approfondi avec suggestions'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();

          // 1. Diagnostic de connexion
          if (args.type === 'connection' || args.type === 'all') {
            const connResult = await client.query('SELECT version() as version, current_database() as database, current_user as user');

            let output = `≡ƒöì **Diagnostic de Connexion**\n\n`;
            output += `Γ£à **Statut**: Connect├⌐\n`;
            output += `≡ƒôè Base: ${connResult.rows[0].database}\n`;
            output += `≡ƒæñ Utilisateur: ${connResult.rows[0].user}\n`;
            output += `≡ƒôï Version: ${connResult.rows[0].version.split(' ')[0]} ${connResult.rows[0].version.split(' ')[1]}\n\n`;

            if (args.type === 'connection') {
              await client.release();
              return output;
            }
          }

          // 2. Diagnostic de performance
          if (args.type === 'performance' || args.type === 'all') {
            const cacheStats = await this.optimizer.getCacheHitRatios();
            const heapRatio = (cacheStats.heap_ratio || 0) * 100;
            const idxRatio = (cacheStats.idx_ratio || 0) * 100;

            let perfOutput = `\n≡ƒôè **Diagnostic de Performance**\n\n`;
            perfOutput += `≡ƒÄ» **Cache Hit Ratio**:\n`;
            perfOutput += `  ΓÇó Tables: ${heapRatio.toFixed(2)}%\n`;
            perfOutput += `  ΓÇó Index: ${idxRatio.toFixed(2)}%\n\n`;

            // Analyse automatique
            if (heapRatio < 95 || idxRatio < 95) {
              perfOutput += `ΓÜá∩╕Å **Probl├¿mes d├⌐tect├⌐s**:\n`;
              if (heapRatio < 95) perfOutput += `  ΓÇó Cache tables faible (${heapRatio.toFixed(2)}%)\n`;
              if (idxRatio < 95) perfOutput += `  ΓÇó Cache index faible (${idxRatio.toFixed(2)}%)\n`;
              perfOutput += `\n≡ƒÆí **Actions recommand├⌐es**:\n`;
              perfOutput += `  1. Augmentez shared_buffers dans postgresql.conf\n`;
              perfOutput += `  2. V├⌐rifiez effective_cache_size\n`;
              perfOutput += `  3. Ex├⌐cutez VACUUM ANALYZE sur les tables actives\n`;
            } else {
              perfOutput += `Γ£à **Performance optimale** - Aucune action n├⌐cessaire\n`;
            }

            // Requ├¬tes lentes
            try {
              const slowQueries = await this.optimizer.getSlowQueries(5);
              if (slowQueries.length > 0) {
                perfOutput += `\n≡ƒÉî **Requ├¬tes lentes d├⌐tect├⌐es** (${slowQueries.length}):\n`;
                slowQueries.slice(0, 3).forEach((q, i) => {
                  perfOutput += `  ${i + 1}. ${q.duration.toFixed(2)}ms - ${q.query.substring(0, 80)}...\n`;
                });
              }
            } catch (e) {
              // pg_stat_statements non activ├⌐
            }

            await client.release();
            return perfOutput;
          }

          return 'Diagnostic termin├⌐';

        } catch (error: any) {
          Logger.error('Γ¥î [diagnose]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      },
    });
  }

  // ============================================================================
  // 2. EXPLORE - Exploration de la Base
  // ============================================================================
  private explore(): void {
    this.server.addTool({
      name: 'explore',
      description: '≡ƒù║∩╕Å Explore et liste les bases, tables, sch├⌐mas et structures',
      parameters: z.object({
        type: z.enum(['databases', 'tables', 'schema', 'structure']).default('tables').describe('Type d\'exploration'),
        target: z.string().optional().describe('Table ou sch├⌐ma sp├⌐cifique'),
        includeSize: z.boolean().default(false).describe('Inclure les tailles'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();

          switch (args.type) {
            case 'databases': {
              const result = await client.query(`
                SELECT datname as database_name, datistemplate as is_template
                FROM pg_database
                WHERE datistemplate = false
                ORDER BY datname
              `);

              const databases = result.rows.map((row: any, index: number) =>
                `${index + 1}. ≡ƒôé ${row.database_name}`
              ).join('\n');

              await client.release();
              return `≡ƒôè **Bases de donn├⌐es** (${result.rows.length}):\n\n${databases}`;
            }

            case 'tables': {
              const schema = args.target || 'public';
              const result = await client.query(`
                SELECT table_name, table_type
                FROM information_schema.tables
                WHERE table_schema = $1
                ORDER BY table_name
              `, [schema]);

              const tables = result.rows.map((row: any, index: number) => {
                const type = row.table_type === 'BASE TABLE' ? '≡ƒôï' : '≡ƒöù';
                return `${index + 1}. ${type} ${row.table_name}`;
              }).join('\n');

              await client.release();
              return `≡ƒôï **Tables du sch├⌐ma '${schema}'** (${result.rows.length}):\n\n${tables}`;
            }

            case 'schema': {
              const tableName = args.target;
              if (!tableName) {
                return 'Γ¥î Veuillez sp├⌐cifier une table avec target: table_name';
              }

              const result = await client.query(`
                SELECT column_name, data_type, character_maximum_length, is_nullable
                FROM information_schema.columns
                WHERE table_name = $1
                ORDER BY ordinal_position
              `, [tableName]);

              const columns = result.rows.map((col: any) => {
                const length = col.character_maximum_length ? `(${col.character_maximum_length})` : '';
                const nullable = col.is_nullable === 'YES' ? 'NULL' : 'NOT NULL';
                return `  ΓÇó ${col.column_name}: ${col.data_type}${length} ${nullable}`;
              }).join('\n');

              await client.release();
              return `≡ƒôï **Structure de '${tableName}'** (${result.rows.length} colonnes):\n\n${columns}`;
            }

            case 'structure': {
              // Vue d'ensemble compl├¿te
              const dbResult = await client.query('SELECT current_database() as db');
              const tablesResult = await client.query(`
                SELECT COUNT(*) as count FROM information_schema.tables WHERE table_schema = 'public'
              `);

              await client.release();

              return `≡ƒù║∩╕Å **Structure de la Base**\n\n` +
                     `≡ƒôè Base: ${dbResult.rows[0].db}\n` +
                     `≡ƒôï Tables: ${tablesResult.rows[0].count}\n` +
                     `≡ƒÆí Utilisez explore avec type: 'tables' pour lister`;
            }

            default:
              return 'Γ¥î Type d\'exploration invalide';
          }

        } catch (error: any) {
          Logger.error('Γ¥î [explore]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      },
    });
  }

  // ============================================================================
  // 3. MCP_PG_VECTOR - Ex├⌐cution SQL avec Guides LLM
  // ============================================================================
  private query(): void {
    this.server.addTool({
      name: 'MCP_PG_VECTOR',
      description: `ΓÜí EX├ëCUTION SQL DIRECTE (PostgreSQL + Vector)

≡ƒöÆ **S├ëCURIT├ë:**
- Par d├⌐faut: readonly=true (SELECT seul)
- Pour INSERT/UPDATE: readonly=false OBLIGATOIRE
- "query" est l'ancien nom, utilisez MAINTENANT "MCP_PG_VECTOR"

≡ƒôï **EXEMPLES:**
MCP_PG_VECTOR({ sql: "SELECT * FROM users", readonly: true })
MCP_PG_VECTOR({ sql: "INSERT INTO logs VALUES ('test')", readonly: false })

≡ƒÆí **POUR L'AGENT:** C'est VOTRE outil principal pour interagir avec la base.`,
      parameters: z.object({
        sql: z.string().describe('Requ├¬te SQL ├á ex├⌐cuter'),
        validateOnly: z.boolean().default(false).describe('Valider sans ex├⌐cuter'),
        readonly: z.boolean().default(true).describe('Mode lecture seule. FALSE = ├ëCRITURE AUTORIS├ëE'),
        limit: z.number().default(100).describe('Limite de r├⌐sultats'),
      }),
      execute: async (args) => {
        try {
          const queryTrimmed = args.sql.trim();
          const queryUpper = queryTrimmed.toUpperCase();
          const queryType = queryTrimmed.split(/\s+/)[0].toUpperCase();
          
          // D├⌐tection du type de requ├¬te pour guide LLM
          const isMutationQuery = /\b(INSERT|UPDATE|DELETE|DROP|CREATE|ALTER|TRUNCATE)\b/.test(queryUpper);
          
          // Validation automatique en mode readonly
          if (args.readonly && isMutationQuery) {
            return `Γ¥î **Requ├¬te bloqu├⌐e en mode lecture seule**

ΓÜá∩╕Å Vous essayez d'ex├⌐cuter une requ├¬te ${queryType} en mode readonly=true

≡ƒöº **CORRECTION REQUISE:**
R├⌐essayez avec: MCP_PG_VECTOR({ sql: "...", readonly: false })

≡ƒÆí **Exemple pour ${queryType}:**
\`\`\`
MCP_PG_VECTOR({
  sql: "${queryType === 'INSERT' ? 'INSERT INTO table (col) VALUES (val)' : queryType === 'UPDATE' ? 'UPDATE table SET col = val WHERE id = X' : 'DELETE FROM table WHERE id = X'}",
  readonly: false
})
\`\`\``;
          }

          // V├⌐rifier que les requ├¬tes SELECT commencent correctement
          if (args.readonly) {
            const safeKeywords = ['SELECT', 'WITH', 'SHOW', 'DESCRIBE', 'EXPLAIN', 'VALUES'];
            if (!safeKeywords.includes(queryType)) {
              return `Γ¥î **Requ├¬te non reconnue en mode lecture**

ΓÜá∩╕Å Le d├⌐but de requ├¬te "${queryType}" n'est pas autoris├⌐ en readonly

≡ƒÆí **Actions possibles:**
1. Pour une lecture: Utilisez SELECT, WITH, ou EXPLAIN
2. Pour une modification: Ajoutez readonly: false`;
            }
          }

          const client = await this.pool.connect();

          try {
            // Limite automatique pour SELECT
            let finalSql = queryTrimmed;
            if (!queryUpper.includes('LIMIT') &&
                (queryUpper.startsWith('SELECT') || queryUpper.startsWith('WITH'))) {
              if (queryUpper.startsWith('SELECT') && !queryUpper.includes('(')) {
                finalSql = `${finalSql} LIMIT ${args.limit}`;
              } else {
                finalSql = `SELECT * FROM (${args.sql}) AS limited_query LIMIT ${args.limit}`;
              }
            }

            const startTime = Date.now();
            const result = await client.query(finalSql);
            const duration = Date.now() - startTime;

            // === OUTPUT ADAPT├ë AU TYPE DE REQU├èTE ===
            
            // Pour les mutations (INSERT, UPDATE, DELETE)
            if (isMutationQuery) {
              let output = `Γ£à **${queryType} ex├⌐cut├⌐ avec succ├¿s**\n\n`;
              output += `ΓÅ▒∩╕Å Dur├⌐e: ${duration}ms\n`;
              output += `≡ƒôè Lignes affect├⌐es: ${result.rowCount || 0}\n`;
              
              // Si RETURNING utilis├⌐, afficher les donn├⌐es retourn├⌐es
              if (result.rows && result.rows.length > 0) {
                output += `\n≡ƒôï **Donn├⌐es retourn├⌐es:**\n`;
                const headers = Object.keys(result.rows[0]);
                output += `| ${headers.join(' | ')} |\n`;
                output += `|${headers.map(() => '---').join('|')}|\n`;
                result.rows.slice(0, 5).forEach((row: any) => {
                  const values = headers.map((h: string) => {
                    const val = row[h];
                    if (val === null) return 'NULL';
                    return String(val).substring(0, 100);
                  });
                  output += `| ${values.join(' | ')} |\n`;
                });
              }
              
              output += `\n≡ƒÆí **Prochaine action sugg├⌐r├⌐e:**\n`;
              if (queryType === 'INSERT') {
                output += `V├⌐rifiez avec: SELECT * FROM ${this.extractTableName(queryTrimmed)} ORDER BY id DESC LIMIT 1`;
              } else if (queryType === 'UPDATE' || queryType === 'DELETE') {
                output += `Confirmez le changement avec une requ├¬te SELECT`;
              }
              
              return output;
            }

            // Pour les SELECT
            let output = `ΓÜí **Requ├¬te ex├⌐cut├⌐e**\n\n`;
            output += `ΓÅ▒∩╕Å Dur├⌐e: ${duration}ms\n`;
            output += `≡ƒôè R├⌐sultats: ${result.rows.length} ligne(s)\n\n`;

            if (result.rows.length > 0) {
              const headers = Object.keys(result.rows[0]);
              output += `| ${headers.join(' | ')} |\n`;
              output += `|${headers.map(() => '---').join('|')}|\n`;

              const displayRows = result.rows.slice(0, 20);
              displayRows.forEach((row: any) => {
                const values = headers.map((h: string) => {
                  const val = row[h];
                  if (val === null) return 'NULL';
                  if (typeof val === 'object') return JSON.stringify(val).substring(0, 300);
                  return String(val).substring(0, 300);
                });
                output += `| ${values.join(' | ')} |\n`;
              });

              if (result.rows.length > 20) {
                output += `\n... et ${result.rows.length - 20} autres lignes`;
              }
            } else {
              output += `Γä╣∩╕Å Aucun r├⌐sultat trouv├⌐\n`;
              output += `\n≡ƒÆí **Suggestions:**\n`;
              output += `- V├⌐rifiez les crit├¿res de recherche\n`;
              output += `- Utilisez explore({ type: 'tables' }) pour lister les tables disponibles`;
            }

            return output;

          } finally {
            await client.release();
          }

        } catch (error: any) {
          Logger.error('Γ¥î [query]', error.message);
          
          // Messages d'erreur contextuels pour LLM
          const errorMsg = error.message.toLowerCase();
          let guidance = '';
          
          if (errorMsg.includes('relation') && errorMsg.includes('does not exist')) {
            const tableName = error.message.match(/relation "([^"]+)"/)?.[1] || 'unknown';
            guidance = `\n\n≡ƒÆí **Guide LLM:** La table "${tableName}" n'existe pas.\n`;
            guidance += `Utilisez explore({ type: 'tables' }) pour voir les tables disponibles.`;
          } else if (errorMsg.includes('column') && errorMsg.includes('does not exist')) {
            const colName = error.message.match(/column "([^"]+)"/)?.[1] || 'unknown';
            guidance = `\n\n≡ƒÆí **Guide LLM:** La colonne "${colName}" n'existe pas.\n`;
            guidance += `Utilisez explore({ type: 'schema', target: 'table_name' }) pour voir les colonnes.`;
          } else if (errorMsg.includes('syntax error')) {
            guidance = `\n\n≡ƒÆí **Guide LLM:** Erreur de syntaxe SQL. V├⌐rifiez:\n`;
            guidance += `- Les guillemets (simples pour valeurs, doubles pour identifiants)\n`;
            guidance += `- Les virgules et parenth├¿ses\n`;
            guidance += `- Les mots-cl├⌐s SQL`;
          } else if (errorMsg.includes('violates foreign key')) {
            guidance = `\n\n≡ƒÆí **Guide LLM:** Contrainte de cl├⌐ ├⌐trang├¿re viol├⌐e.\n`;
            guidance += `V├⌐rifiez que l'ID r├⌐f├⌐renc├⌐ existe dans la table parent.`;
          }
          
          return `Γ¥î **Erreur SQL:** ${error.message}${guidance}`;
        }
      },
    });
  }

  /**
   * Extrait le nom de table d'une requ├¬te INSERT/UPDATE/DELETE
   */
  private extractTableName(sql: string): string {
    const insertMatch = sql.match(/INSERT\s+INTO\s+(\w+)/i);
    if (insertMatch) return insertMatch[1];
    
    const updateMatch = sql.match(/UPDATE\s+(\w+)/i);
    if (updateMatch) return updateMatch[1];
    
    const deleteMatch = sql.match(/DELETE\s+FROM\s+(\w+)/i);
    if (deleteMatch) return deleteMatch[1];
    
    return 'table_name';
  }

