  // ============================================================================
  // 5. INSERT - Insertion Simplifi├⌐e
  // ============================================================================
  private insert(): void {
    this.server.addTool({
      name: 'insert',
      description: '≡ƒôÑ Ins├¿re des donn├⌐es avec ou sans vecteur g├⌐n├⌐r├⌐ automatiquement',
      parameters: z.object({
        table: z.string().describe('Nom de la table'),
        data: z.record(z.any()).describe('Donn├⌐es ├á ins├⌐rer (objet JSON)'),
        generateEmbedding: z.boolean().default(false).describe('G├⌐n├⌐rer un embedding automatiquement (Qwen 8B)'),
        dimensions: z.number().default(4096).describe('Dimensions du vecteur (4096 pour Qwen)'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();

          // Construire les colonnes et valeurs
          const columns: string[] = [];
          const values: any[] = [];
          let paramIndex = 1;

          // Ajouter les donn├⌐es
          for (const [key, value] of Object.entries(args.data)) {
            columns.push(key);
            values.push(value);
          }

          // G├⌐n├⌐rer l'embedding si demand├⌐
          if (args.generateEmbedding) {
            const textParts: string[] = [];
            if (args.data.llm_interpretation) textParts.push(args.data.llm_interpretation);
            if (args.data.study_name) textParts.push(`Study: ${args.data.study_name}`);
            if (args.data.symbol) textParts.push(`Symbol: ${args.data.symbol}`);
            if (args.data.technical_data) textParts.push(`Technical: ${JSON.stringify(args.data.technical_data)}`);

            const embeddingText = textParts.join(' | ') || JSON.stringify(args.data);
            Logger.info(`≡ƒöä G├⌐n├⌐ration embedding pour: "${embeddingText.substring(0, 50)}..."`);

            const embedding = await embeddingService.generateEmbedding(embeddingText, {
              dimensions: args.dimensions
            });

            columns.push('embedding');
            values.push(`[${embedding.join(',')}]`);
          }

          // Construire la requ├¬te
          const placeholders = columns.map(() => `$${paramIndex++}`).join(', ');
          const query = `INSERT INTO ${args.table} (${columns.join(', ')}) VALUES (${placeholders}) RETURNING *`;

          const result = await client.query(query, values);
          await client.release();

          return `Γ£à **Insertion r├⌐ussie**\n\n` +
                 `≡ƒôï Table: ${args.table}\n` +
                 `≡ƒôè Lignes: ${result.rows.length}\n` +
                 `≡ƒöæ ID: ${result.rows[0].id || 'N/A'}\n` +
                 `${args.generateEmbedding ? '≡ƒºá Embedding g├⌐n├⌐r├⌐: ' + args.dimensions + 'D\n' : ''}`;

        } catch (error: any) {
          Logger.error('Γ¥î [insert]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      },
    });
  }

  // ============================================================================
  // 6. MANAGE_VECTORS - Gestion Vectorielle
  // ============================================================================
  private manageVectors(): void {
    this.server.addTool({
      name: 'manage_vectors',
      description: '≡ƒº¼ Gestion compl├¿te des vecteurs : cr├⌐ation, index, statistiques, optimisation',
      parameters: z.object({
        action: z.enum(['create', 'index', 'stats', 'optimize', 'list']).describe('Action ├á effectuer'),
        table: z.string().describe('Nom de la table'),
        column: z.string().default('embedding').describe('Colonne vectorielle'),
        dimensions: z.number().default(4096).describe('Dimensions du vecteur (4096 pour Qwen)'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();

          switch (args.action) {
            case 'create': {
              const query = `
                CREATE TABLE IF NOT EXISTS ${args.table} (
                  id SERIAL PRIMARY KEY,
                  ${args.column} vector(${args.dimensions}),
                  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                );
              `;
              await client.query(query);
              await client.release();
              return `Γ£à **Table vectorielle cr├⌐├⌐e**\n\n≡ƒôï Table: ${args.table}\n≡ƒº¼ Colonne: ${args.column} (${args.dimensions}D)`;
            }

            case 'index': {
              const indexName = `${args.table}_${args.column}_idx`;
              const query = `CREATE INDEX IF NOT EXISTS ${indexName} ON ${args.table} USING ivfflat (${args.column} vector_cosine_ops) WITH (lists = 100);`;
              await client.query(query);
              await client.release();
              return `Γ£à **Index vectoriel cr├⌐├⌐**\n\n≡ƒôï Table: ${args.table}\n≡ƒº¼ Index: ${indexName}\n≡ƒÄ» Type: IVFFlat (cosine)`;
            }

            case 'stats': {
              const result = await client.query(`
                SELECT COUNT(*) as total_rows,
                       AVG(array_length(${args.column}, 1)) as avg_dimensions
                FROM ${args.table}
                WHERE ${args.column} IS NOT NULL
              `);
              await client.release();
              return `≡ƒôè **Statistiques Vectorielles**\n\n≡ƒôï Table: ${args.table}\n≡ƒôê Lignes: ${result.rows[0].total_rows}\n≡ƒº¼ Dimensions: ${result.rows[0].avg_dimensions || args.dimensions}`;
            }

            case 'optimize': {
              await client.query(`VACUUM ANALYZE ${args.table}`);
              await client.release();
              return `Γ£à **Optimisation termin├⌐e**\n\n≡ƒôï Table: ${args.table}\n≡ƒº╣ VACUUM ANALYZE ex├⌐cut├⌐`;
            }

            case 'list': {
              const result = await client.query(`
                SELECT table_name, column_name, data_type
                FROM information_schema.columns
                WHERE data_type = 'vector'
                ORDER BY table_name
              `);
              await client.release();

              if (result.rows.length === 0) {
                return 'Γä╣∩╕Å **Aucune table vectorielle trouv├⌐e**';
              }

              const tables = result.rows.map((row: any, index: number) =>
                `${index + 1}. ≡ƒôï ${row.table_name}.${row.column_name} (${row.data_type})`
              ).join('\n');

              return `≡ƒº¼ **Tables Vectorielles** (${result.rows.length}):\n\n${tables}`;
            }

            default:
              return 'Γ¥î Action invalide';
          }

        } catch (error: any) {
          Logger.error('Γ¥î [manage_vectors]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      },
    });
  }

  // ============================================================================
  // 7. OPTIMIZE - Optimisation
  // ============================================================================
  private optimize(): void {
    this.server.addTool({
      name: 'optimize',
      description: 'ΓÜí Optimise la base de donn├⌐es (index, requ├¬tes, performances)',
      parameters: z.object({
        target: z.enum(['indexes', 'queries', 'tables', 'all']).default('all').describe('Cible d\'optimisation'),
      }),
      execute: async (args) => {
        try {
          let output = `ΓÜí **Optimisation de la Base**\n\n`;

          if (args.target === 'indexes' || args.target === 'all') {
            const indexes = await this.optimizer.analyzeIndexUsage();
            const unused = indexes.filter(idx => idx.usage === 0);

            if (unused.length > 0) {
              output += `≡ƒùæ∩╕Å **Index non utilis├⌐s** (${unused.length}):\n`;
              unused.slice(0, 5).forEach(idx => {
                output += `  ΓÇó ${idx.indexname} sur ${idx.tablename}\n`;
              });
              output += `\n≡ƒÆí Supprimez ces index pour am├⌐liorer les performances d'├⌐criture\n\n`;
            } else {
              output += `Γ£à **Index**: Tous bien utilis├⌐s\n\n`;
            }
          }

          if (args.target === 'queries' || args.target === 'all') {
            try {
              const slowQueries = await this.optimizer.getSlowQueries(5);
              if (slowQueries.length > 0) {
                output += `≡ƒÉî **Requ├¬tes lentes** (${slowQueries.length}):\n`;
                slowQueries.forEach((q, i) => {
                  output += `  ${i + 1}. ${q.duration.toFixed(2)}ms\n`;
                });
                output += `\n≡ƒÆí Analysez et optimisez ces requ├¬tes\n\n`;
              }
            } catch {
              output += `Γä╣∩╕Å **Requ├¬tes lentes**: pg_stat_statements non activ├⌐\n\n`;
            }
          }

          if (args.target === 'tables' || args.target === 'all') {
            const stats = await this.optimizer.getTableStatistics();
            const needVacuum = stats.filter(s => {
              const deadRatio = s.n_live_tup > 0 ? (s.n_dead_tup / (s.n_live_tup + s.n_dead_tup)) : 0;
              return deadRatio > 0.1;
            });

            if (needVacuum.length > 0) {
              output += `≡ƒº╣ **Tables n├⌐cessitant VACUUM** (${needVacuum.length}):\n`;
              needVacuum.slice(0, 3).forEach(t => {
                const deadRatio = t.n_live_tup > 0 ? (t.n_dead_tup / (t.n_live_tup + t.n_dead_tup) * 100).toFixed(1) : '0';
                output += `  ΓÇó ${t.tablename}: ${deadRatio}% tuples morts\n`;
              });
              output += `\n≡ƒÆí Ex├⌐cutez VACUUM ANALYZE sur ces tables\n\n`;
            } else {
              output += `Γ£à **Tables**: Aucune action n├⌐cessaire\n\n`;
            }
          }

          return output;

        } catch (error: any) {
          Logger.error('Γ¥î [optimize]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      },
    });
  }

  // ============================================================================
  // 8. VECTORIZE_ROW - Vectorisation ├á la demande
  // ============================================================================
  private vectorize_row(): void {
    this.server.addTool({
      name: 'vectorize_row',
      description: '≡ƒºá G├⌐n├¿re et sauvegarde un embedding pour une ligne existante (Qwen 8B)',
      parameters: z.object({
        table: z.string().describe('Nom de la table'),
        id: z.string().describe('ID de la ligne (UUID ou Integer)'),
        text_columns: z.array(z.string()).describe('Colonnes ├á utiliser pour le texte source'),
        target_column: z.string().default('embedding').describe('Colonne cible pour le vecteur'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();
          try {
             // 1. Fetch content
             const cols = args.text_columns.map(c => `COALESCE(${c}, '')`).join(" || ' ' || ");
             const selectQuery = `SELECT ${cols} as combined_text FROM ${args.table} WHERE id = $1`;
             
             // Dynamic ID typing check (simple heuristic)
             const idVal = args.id; 
             
             const res = await client.query(selectQuery, [idVal]);
             if (res.rows.length === 0) return "Γ¥î ID introuvable";
             
             const text = res.rows[0].combined_text;
             if (!text || text.length < 5) return "ΓÜá∩╕Å Texte trop court pour vectoriser";

             // 2. Generate
             const vector = await embeddingService.generateEmbedding(text, { dimensions: 4096 });
             
             // 3. Update
             const vectorStr = `[${vector.join(',')}]`;
             await client.query(
                 `UPDATE ${args.table} SET ${args.target_column} = $1::vector WHERE id = $2`,
                 [vectorStr, idVal]
             );
             
             return `Γ£à Vecteur ${vector.length} dims g├⌐n├⌐r├⌐ et sauvegard├⌐ pour ID ${args.id}`;

          } finally {
            client.release();
          }
        } catch (error: any) {
          Logger.error('Γ¥î [vectorize_row]', error.message);
          return `Γ¥î Erreur: ${error.message}`;
        }
      }
    });
  }

