  // ========================================================================
  // 1. V├⌐rifier si l'extension pg_vector est install├⌐e
  // ========================================================================
  private checkExtension(): void {
    this.server.addTool({
      name: 'pgvector_check_extension',
      description: 'V├⌐rifie si l\'extension pg_vector est install├⌐e et retourne sa version',
      parameters: z.object({
        autoInstall: z.boolean().optional().default(false).describe('Installer automatiquement l\'extension si absente'),
      }),
      execute: async (args) => {
        try {
          const client = await this.pool.connect();

          // V├⌐rifier si l'extension existe
          const checkResult = await client.query(`
            SELECT EXISTS(
              SELECT 1 FROM pg_extension WHERE extname = 'vector'
            ) as installed
          `);

          const isInstalled = checkResult.rows[0].installed;

          if (!isInstalled) {
            if (args.autoInstall) {
              await client.query('CREATE EXTENSION IF NOT EXISTS vector');
              Logger.info('Γ£à Extension pg_vector install├⌐e');
              await client.release();
              return 'Γ£à Extension pg_vector install├⌐e avec succ├¿s';
            } else {
              await client.release();
              return 'Γ¥î Extension pg_vector non install├⌐e. Utilisez autoInstall:true pour l\'installer automatiquement.\n\n' +
                     '≡ƒÆí Installation manuelle: CREATE EXTENSION vector;';
            }
          }

          // R├⌐cup├⌐rer la version
          const versionResult = await client.query(`
            SELECT extversion as version
            FROM pg_extension
            WHERE extname = 'vector'
          `);

          await client.release();

          const version = versionResult.rows[0].version;
          return `Γ£à Extension pg_vector install├⌐e (version: ${version})`;
        } catch (error: any) {
          Logger.error('Γ¥î [pgvector_check_extension]', error.message);

          // Message d'erreur am├⌐lior├⌐ pour l'extension non disponible
          if (error.message.includes('could not open extension control file') ||
              error.message.includes('extension "vector" is not available') ||
              error.message.includes('No such file or directory')) {
            return `Γ¥î **Extension pg_vector non disponible sur ce serveur PostgreSQL**

L'extension pg_vector doit ├¬tre install├⌐e sur le serveur PostgreSQL avant de pouvoir l'utiliser.

≡ƒôª **Installation sur Linux/Ubuntu:**
\`\`\`bash
# Pour PostgreSQL 14+
sudo apt-get install postgresql-14-pgvector
# Ou compiler depuis les sources
git clone --branch v0.5.1 https://github.com/pgvector/pgvector.git
cd pgvector
make
sudo make install
\`\`\`

≡ƒôª **Installation sur macOS (Homebrew):**
\`\`\`bash
brew install pgvector
\`\`\`

≡ƒôª **Activation dans PostgreSQL:**
\`\`\`sql
-- Se connecter ├á la base de donn├⌐es
\\c votre_base

-- Cr├⌐er l'extension
