        };

        if (args.topic === 'all') {
          output += topics.create + '\n';
          output += topics.insert + '\n';
          output += topics.search + '\n';
          output += topics.functions + '\n';
          output += topics.errors + '\n';
        } else {
          output += topics[args.topic];
        }

        output += `\n---\n≡ƒÆí **Conseil LLM:** Utilisez toujours \`pgvector_insert_vector\` et \`pgvector_search\` au lieu d'├⌐crire du SQL brut!\n`;

        return output;
      },
    });
  }
