import { Pool } from 'pg';

// Types pour les analyses d'optimisation
export interface SlowQuery {
  query: string;
  duration: number;
  calls: number;
  mean_time: number;
  total_time: number;
}

export interface IndexInfo {
  tablename: string;
  indexname: string;
  indexdef: string;
  size: string;
  usage: number;
}

export interface TableStats {
  tablename: string;
  seq_scan: number;
  seq_tup_read: number;
  idx_scan: number;
  idx_tup_fetch: number;
  n_tup_ins: number;
  n_tup_upd: number;
  n_tup_del: number;
  n_live_tup: number;
  n_dead_tup: number;
  last_vacuum?: string;
  last_autovacuum?: string;
  last_analyze?: string;
  last_autoanalyze?: string;
}

export interface MissingIndex {
  table: string;
  columns: string;
  suggested_index: string;
  potential_impact: 'HIGH' | 'MEDIUM' | 'LOW';
  estimated_gain: string;
}

// Classe pour l'optimisation de base de donn├â┬⌐es
export class DBOptimizer {
  constructor(private pool: Pool) {}

  // Obtenir les requ├â┬¬tes lentes depuis pg_stat_statements
  async getSlowQueries(limit: number = 10): Promise<SlowQuery[]> {
    const query = `
      SELECT
        query,
        calls,
        total_exec_time as total_time,
        mean_exec_time as mean_time,
        total_exec_time / calls as avg_time
      FROM pg_stat_statements
      ORDER BY mean_exec_time DESC
      LIMIT $1
    `;

    try {
      const result = await this.pool.query(query, [limit]);
      return result.rows.map(row => ({
        query: row.query,
        duration: parseFloat(row.mean_time),
        calls: parseInt(row.calls),
        mean_time: parseFloat(row.mean_time),
        total_time: parseFloat(row.total_time)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de la r├â┬⌐cup├â┬⌐ration des requ├â┬¬tes lentes: ${error.message}`);
    }
  }

  // Analyser l'utilisation des index
  async analyzeIndexUsage(): Promise<IndexInfo[]> {
    const query = `
      SELECT
        i.schemaname,
        i.tablename,
        i.indexname,
        i.indexdef,
        pg_size_pretty(pg_relation_size(s.indexrelid)) as size,
        s.idx_scan as usage
      FROM pg_indexes i
      JOIN pg_stat_user_indexes s ON i.tablename = s.relname AND i.indexname = s.indexrelname AND i.schemaname = s.schemaname
      WHERE i.schemaname = 'public'
      ORDER BY s.idx_scan ASC, pg_relation_size(s.indexrelid) DESC
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows.map(row => ({
        tablename: row.tablename,
        indexname: row.indexname,
        indexdef: row.indexdef,
        size: row.size,
        usage: parseInt(row.usage || 0)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse des index: ${error.message}`);
    }
  }

  // Obtenir les statistiques des tables
  async getTableStatistics(): Promise<TableStats[]> {
    const query = `
      SELECT
        schemaname,
        relname as tablename,
        seq_scan,
        seq_tup_read,
        idx_scan,
        idx_tup_fetch,
        n_tup_ins,
        n_tup_upd,
        n_tup_del,
        n_live_tup,
        n_dead_tup,
        last_vacuum,
        last_autovacuum,
        last_analyze,
        last_autoanalyze,
        vacuum_count,
        autovacuum_count,
        analyze_count,
        autoanalyze_count
      FROM pg_stat_user_tables
      WHERE schemaname = 'public'
      ORDER BY (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) DESC
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows.map(row => ({
        tablename: row.tablename,
        seq_scan: parseInt(row.seq_scan || 0),
        seq_tup_read: parseInt(row.seq_tup_read || 0),
        idx_scan: parseInt(row.idx_scan || 0),
        idx_tup_fetch: parseInt(row.idx_tup_fetch || 0),
        n_tup_ins: parseInt(row.n_tup_ins || 0),
        n_tup_upd: parseInt(row.n_tup_upd || 0),
        n_tup_del: parseInt(row.n_tup_del || 0),
        n_live_tup: parseInt(row.n_live_tup || 0),
        n_dead_tup: parseInt(row.n_dead_tup || 0),
        last_vacuum: row.last_vacuum,
        last_autovacuum: row.last_autovacuum,
        last_analyze: row.last_analyze,
        last_autoanalyze: row.last_autoanalyze
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de la r├â┬⌐cup├â┬⌐ration des statistiques: ${error.message}`);
    }
  }

  // Sugg├â┬⌐rer des index manquants bas├â┬⌐s sur les requ├â┬¬tes lentes
  async suggestMissingIndexes(): Promise<MissingIndex[]> {
    const suggestions: MissingIndex[] = [];

    // Analyser les requ├â┬¬tes avec beaucoup de seq_scan
    const tablesWithHighSeqScan = await this.pool.query(`
      SELECT
        relname as tablename,
        seq_scan,
        seq_tup_read
      FROM pg_stat_user_tables
      WHERE seq_scan > 1000
        AND seq_tup_read > 10000
      ORDER BY seq_scan DESC
    `);

    for (const table of tablesWithHighSeqScan.rows) {
      // Sugg├â┬⌐rer des index bas├â┬⌐s sur les colonnes fr├â┬⌐quemment utilis├â┬⌐es dans WHERE
      const commonWhereColumns = await this.pool.query(`
        SELECT
          attname as column_name
        FROM pg_attribute a
        JOIN pg_class c ON a.attrelid = c.oid
        JOIN pg_namespace n ON c.relnamespace = n.oid
        WHERE c.relname = $1
          AND n.nspname = 'public'
          AND a.attnum > 0
          AND NOT a.attisdropped
          AND a.attnotnull = true
        ORDER BY a.attnum
      `, [table.tablename]);

      if (commonWhereColumns.rows.length > 0) {
        const columns = commonWhereColumns.rows
          .slice(0, 3) // Prendre les 3 premi├â┬¿res colonnes
          .map(col => col.column_name)
          .join(', ');

        suggestions.push({
          table: table.tablename,
          columns,
          suggested_index: `CREATE INDEX idx_${table.tablename}_${commonWhereColumns.rows[0].column_name} ON ${table.tablename} (${columns});`,
          potential_impact: table.seq_scan > 10000 ? 'HIGH' : 'MEDIUM',
          estimated_gain: `R├â┬⌐duction potentielle de ${Math.round((table.seq_scan / (table.seq_scan + 100)) * 100)}% des sequential scans`
        });
      }
    }

    return suggestions;
  }

  // Analyser les tables qui n├â┬⌐cessitent un VACUUM
  async getTablesNeedingVacuum(): Promise<any[]> {
    const query = `
      SELECT
        schemaname,
        relname as tablename,
        n_live_tup,
        n_dead_tup,
        (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) * 100 as dead_tuple_percent,
        last_vacuum,
        last_autovacuum,
        last_analyze,
        last_autoanalyze,
        pg_size_pretty(pg_total_relation_size(schemaname||'.'||relname)) as table_size
      FROM pg_stat_user_tables
      WHERE schemaname = 'public'
        AND n_dead_tup > 1000
        AND (n_dead_tup::float / GREATEST(n_live_tup + n_dead_tup, 1)) > 0.1
      ORDER BY dead_tuple_percent DESC
    `;

    try {
      const result = await this.pool.query(query);
      // Formatter dead_tuple_percent en JavaScript (plus compatible)
      return result.rows.map(row => ({
        ...row,
        dead_tuple_percent: parseFloat(row.dead_tuple_percent || 0).toFixed(2)
      }));
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse VACUUM: ${error.message}`);
    }
  }

  // Obtenir les informations de cache
  async getCacheHitRatios(): Promise<any> {
    const query = `
      SELECT
        sum(heap_blks_read) as heap_read,
        sum(heap_blks_hit) as heap_hit,
        sum(heap_blks_hit) / nullif(sum(heap_blks_hit) + sum(heap_blks_read), 0) as heap_ratio,
        sum(idx_blks_read) as idx_read,
        sum(idx_blks_hit) as idx_hit,
        sum(idx_blks_hit) / nullif(sum(idx_blks_hit) + sum(idx_blks_read), 0) as idx_ratio
      FROM pg_statio_user_tables;
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows[0];
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse du cache: ${error.message}`);
    }
  }

  // Analyser les locks actifs
  async getActiveLocks(): Promise<any[]> {
    const query = `
      SELECT
        t.relname as table_name,
        l.mode,
        l.granted,
        a.usename as username,
        a.query,
        a.query_start,
        now() - a.query_start as duration
      FROM pg_locks l
      JOIN pg_class t ON l.relation = t.oid
      JOIN pg_stat_activity a ON l.pid = a.pid
      WHERE t.relname IS NOT NULL
        AND l.mode NOT IN ('AccessShareLock')
      ORDER BY a.query_start;
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows;
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse des locks: ${error.message}`);
    }
  }

  // Analyser les requ├â┬¬tes en cours d'ex├â┬⌐cution
  async getRunningQueries(): Promise<any[]> {
    const query = `
      SELECT
        pid,
        usename as username,
        application_name,
        client_addr,
        state,
        query,
        query_start,
        now() - query_start as duration,
        wait_event_type,
        wait_event
      FROM pg_stat_activity
      WHERE state != 'idle'
        AND query NOT LIKE '%pg_stat_activity%'
      ORDER BY query_start;
    `;

    try {
      const result = await this.pool.query(query);
      return result.rows;
    } catch (error: any) {
      throw new Error(`Erreur lors de l'analyse des requ├â┬¬tes: ${error.message}`);
    }
  }

  // G├â┬⌐n├â┬⌐rer un rapport d'optimisation complet
  async generateOptimizationReport(): Promise<string> {
    try {
      const report = [];

      report.push('# ├░┼╕ΓÇ£┼á Rapport d\'Optimisation PostgreSQL\n');
      report.push(`*G├â┬⌐n├â┬⌐r├â┬⌐ le ${new Date().toLocaleString('fr-FR')}*\n`);

      // 1. Cache Hit Ratios
      const cacheStats = await this.getCacheHitRatios();
      report.push('## ├░┼╕┼╜┬» Performance du Cache');
      report.push(`- **Cache tables**: ${((cacheStats.heap_ratio || 0) * 100).toFixed(2)}%`);
      report.push(`- **Cache index**: ${((cacheStats.idx_ratio || 0) * 100).toFixed(2)}%`);

      if ((cacheStats.heap_ratio || 0) < 0.95) {
        report.push('├ó┼í┬á├»┬╕  **Recommandation**: Augmenter shared_buffers pour am├â┬⌐liorer le cache hit ratio');
      }
      report.push('');

      // 2. Tables n├â┬⌐cessitant un VACUUM
      const vacuumTables = await this.getTablesNeedingVacuum();
      if (vacuumTables.length > 0) {
        report.push('## ├░┼╕┬º┬╣ Tables n├â┬⌐cessitant un VACUUM');
        vacuumTables.slice(0, 5).forEach(table => {
          report.push(`- **${table.tablename}**: ${table.dead_tuple_percent}% de tuples morts (${table.table_size})`);
        });
        report.push('');
      }

      // 3. Index non utilis├â┬⌐s
      const unusedIndexes = await this.analyzeIndexUsage();
      const unused = unusedIndexes.filter(idx => idx.usage === 0);
      if (unused.length > 0) {
        report.push('## ├░┼╕ΓÇöΓÇÿ├»┬╕  Index non utilis├â┬⌐s');
        unused.slice(0, 3).forEach(idx => {
          report.push(`- **${idx.indexname}** sur ${idx.tablename} (${idx.size})`);
        });
        report.push('├░┼╕ΓÇÖ┬í **Action**: Consid├â┬⌐rez supprimer ces index pour am├â┬⌐liorer les performances d\'├â┬⌐criture');
        report.push('');
      }

      // 4. Requ├â┬¬tes lentes (si pg_stat_statements est activ├â┬⌐)
      try {
        const slowQueries = await this.getSlowQueries(3);
        if (slowQueries.length > 0) {
          report.push('## ├░┼╕ ┼Æ Requ├â┬¬tes lentes');
          slowQueries.forEach((query, index) => {
            report.push(`${index + 1}. **Temps moyen**: ${query.duration.toFixed(2)}ms (${query.calls} appels)`);
            report.push(`   \`\`\`sql\n${query.query.substring(0, 100)}...\n   \`\`\``);
          });
          report.push('');
        }
      } catch (e) {
        // pg_stat_statements n'est peut-├â┬¬tre pas activ├â┬⌐
        report.push('## ├░┼╕ΓÇ£╦å Note');
        report.push('Activer `pg_stat_statements` pour analyser les requ├â┬¬tes lentes');
        report.push('');
      }

      // 5. Suggestions d'index
      const missingIndexes = await this.suggestMissingIndexes();
      if (missingIndexes.length > 0) {
        report.push('## ├░┼╕ΓÇÖ┬í Suggestions d\'index');
        missingIndexes.slice(0, 3).forEach(idx => {
          report.push(`- **${idx.table}** (${idx.potential_impact} impact)`);
          report.push(`  ${idx.suggested_index}`);
        });
        report.push('');
      }

      // 6. Requ├â┬¬tes actives et locks
      const activeQueries = await this.getRunningQueries();
      const activeLocks = await this.getActiveLocks();

      if (activeQueries.length > 0 || activeLocks.length > 0) {
        report.push('## ├ó┼í┬í Activit├â┬⌐ actuelle');
        if (activeQueries.length > 0) {
          report.push(`- **${activeQueries.length} requ├â┬¬te(s) en cours d'ex├â┬⌐cution**`);
        }
        if (activeLocks.length > 0) {
          report.push(`- **${activeLocks.length} lock(s) actif(s)**`);
        }
        report.push('');
      }

      return report.join('\n');
    } catch (error: any) {
      return `├ó ┼Æ Erreur lors de la g├â┬⌐n├â┬⌐ration du rapport: ${error.message}`;
    }
  }
}

import { z } from 'zod';

// Types pour la validation SQL
export interface SQLValidationResult {
  valid: boolean;
  error?: string;
  analysis?: string;
  suggestion?: string;
}

// Mots-cl├⌐s dangereux qui n├⌐cessitent une attention particuli├¿re
const DANGEROUS_KEYWORDS = [
  'DROP', 'DELETE', 'TRUNCATE', 'UPDATE', 'INSERT', 'CREATE', 'ALTER',
  'GRANT', 'REVOKE', 'EXECUTE', 'UNION', 'EXEC', 'sp_executesql'
];

// Validation basique de syntaxe SQL
export function validateSQL(query: string): SQLValidationResult {
  if (!query || query.trim().length === 0) {
    return {
      valid: false,
      error: 'La requ├¬te SQL est vide',
      suggestion: 'Veuillez fournir une requ├¬te SQL valide'
    };
  }

  const trimmedQuery = query.trim().toUpperCase();

  // V├⌐rifier les parenth├¿ses
  const openParens = (query.match(/\(/g) || []).length;
  const closeParens = (query.match(/\)/g) || []).length;

  if (openParens !== closeParens) {
    return {
      valid: false,
      error: 'Parenth├¿ses non ├⌐quilibr├⌐es',
      suggestion: 'V├⌐rifiez que toutes les parenth├¿ses ouvertes sont ferm├⌐es'
    };
  }

  // V├⌐rifier les guillemets
  const singleQuotes = (query.match(/'/g) || []).length;
  if (singleQuotes % 2 !== 0) {
    return {
      valid: false,
      error: 'Guillemets simples non ├⌐quilibr├⌐s',
      suggestion: 'V├⌐rifiez que toutes les cha├«nes de caract├¿res sont correctement quot├⌐es'
    };
  }

  // Analyser le type de requ├¬te
  let analysis = '';
  let warnings: string[] = [];

  if (trimmedQuery.startsWith('SELECT')) {
    analysis = 'Requ├¬te de s├⌐lection de donn├⌐es';

    // V├⌐rifier les potentiels probl├¿mes de performance
    if (trimmedQuery.includes('SELECT *')) {
      warnings.push('SELECT * peut retourner plus de colonnes que n├⌐cessaire');
    }

    if (!trimmedQuery.includes('WHERE') && !trimmedQuery.includes('LIMIT')) {
      warnings.push('Consid├⌐rez ajouter une clause WHERE ou LIMIT pour limiter les r├⌐sultats');
    }

    if (trimmedQuery.includes('ORDER BY') && !trimmedQuery.includes('LIMIT')) {
      warnings.push('ORDER BY sans LIMIT peut ├¬tre co├╗teux sur de grands jeux de donn├⌐es');
    }
  } else if (trimmedQuery.startsWith('INSERT')) {
    analysis = 'Requ├¬te d\'insertion de donn├⌐es';
    warnings.push('Les requ├¬tes d\'├⌐criture modifient la base de donn├⌐es');
  } else if (trimmedQuery.startsWith('UPDATE')) {
    analysis = 'Requ├¬te de mise ├á jour de donn├⌐es';
    if (!trimmedQuery.includes('WHERE')) {
      warnings.push('UPDATE sans WHERE va modifier toutes les lignes !');
    }
  } else if (trimmedQuery.startsWith('DELETE')) {
    analysis = 'Requ├¬te de suppression de donn├⌐es';
    if (!trimmedQuery.includes('WHERE')) {
      warnings.push('DELETE sans WHERE va supprimer toutes les lignes !');
    }
  } else if (trimmedQuery.startsWith('DROP')) {
    analysis = 'Requ├¬te de suppression d\'objet (table, vue, etc.)';
    warnings.push('DROP est une op├⌐ration irr├⌐versible !');
  } else if (trimmedQuery.startsWith('CREATE')) {
    analysis = 'Requ├¬te de cr├⌐ation d\'objet';
  } else if (trimmedQuery.startsWith('ALTER')) {
    analysis = 'Requ├¬te de modification de structure';
    warnings.push('ALTER modifie la structure de la base de donn├⌐es');
  } else if (trimmedQuery.startsWith('EXPLAIN')) {
    analysis = 'Requ├¬te d\'analyse de plan d\'ex├⌐cution';
  } else {
    analysis = 'Type de requ├¬te non identifi├⌐';
  }

  // V├⌐rifier les mots-cl├⌐s potentiellement dangereux
  const foundDangerous = DANGEROUS_KEYWORDS.filter(keyword =>
    trimmedQuery.includes(keyword) && !trimmedQuery.startsWith('SELECT') || keyword === 'UNION'
  );

  if (foundDangerous.length > 0) {
    warnings.push(`Mots-cl├⌐s sensibles d├⌐tect├⌐s: ${foundDangerous.join(', ')}`);
  }

  // Construire la suggestion si il y a des avertissements
  let suggestion = '';
  if (warnings.length > 0) {
    suggestion = warnings.join('\n');
  } else {
    suggestion = 'La requ├¬te semble syntaxiquement correcte';
  }

  return {
    valid: true,
    analysis: `${analysis}${warnings.length > 0 ? '\n\nΓÜá∩╕Å Avertissements:' : ''}`,
    suggestion
  };
}

// Formater une requ├¬te SQL (basique)
export function formatSQL(query: string): string {
  if (!query) return '';

  // Mettre en majuscules les mots-cl├⌐s SQL principaux
  const keywords = [
    'SELECT', 'FROM', 'WHERE', 'AND', 'OR', 'NOT', 'IN', 'LIKE', 'BETWEEN',
    'INSERT', 'INTO', 'VALUES', 'UPDATE', 'SET', 'DELETE', 'CREATE', 'DROP',
    'ALTER', 'TABLE', 'INDEX', 'VIEW', 'AS', 'JOIN', 'INNER', 'LEFT', 'RIGHT',
    'OUTER', 'ON', 'GROUP', 'BY', 'HAVING', 'ORDER', 'ASC', 'DESC', 'LIMIT',
    'OFFSET', 'UNION', 'ALL', 'DISTINCT', 'COUNT', 'SUM', 'AVG', 'MIN', 'MAX',
    'EXISTS', 'CASE', 'WHEN', 'THEN', 'ELSE', 'END', 'IF', 'NULL', 'IS',
    'TRUE', 'FALSE', 'AND', 'OR', 'XOR'
  ];

  let formatted = query;

  // Mettre en majuscules les mots-cl├⌐s (en ├⌐vitant les valeurs litt├⌐rales)
  keywords.forEach(keyword => {
    const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
    formatted = formatted.replace(regex, keyword);
  });

  // Ajouter des sauts de ligne apr├¿s les mots-cl├⌐s principaux
  const lineBreakKeywords = ['SELECT', 'FROM', 'WHERE', 'GROUP BY', 'HAVING', 'ORDER BY'];
  lineBreakKeywords.forEach(keyword => {
    const regex = new RegExp(`\\b${keyword}\\b`, 'gi');
    formatted = formatted.replace(regex, `\n${keyword}`);
  });

  // Nettoyer les espaces multiples
  formatted = formatted.replace(/\s+/g, ' ').trim();

  return formatted;
}

// Analyser une requ├¬te pour extraire des informations
export function analyzeQuery(query: string): {
  tables: string[];
  columns: string[];
  operations: string[];
  estimatedComplexity: 'LOW' | 'MEDIUM' | 'HIGH';
} {
  const tables: string[] = [];
  const columns: string[] = [];
  const operations: string[] = [];
  let estimatedComplexity: 'LOW' | 'MEDIUM' | 'HIGH' = 'LOW';

  const upperQuery = query.toUpperCase();

  // Extraire les op├⌐rations
  if (upperQuery.includes('SELECT')) operations.push('SELECT');
  if (upperQuery.includes('INSERT')) operations.push('INSERT');
  if (upperQuery.includes('UPDATE')) operations.push('UPDATE');
  if (upperQuery.includes('DELETE')) operations.push('DELETE');
  if (upperQuery.includes('JOIN')) operations.push('JOIN');
  if (upperQuery.includes('UNION')) operations.push('UNION');
  if (upperQuery.includes('SUBQUERY') || upperQuery.match(/\(.*SELECT.*\)/)) {
    operations.push('SUBQUERY');
  }

  // Extraire les tables (simplifi├⌐)
  const fromMatch = query.match(/FROM\s+([a-zA-Z_][a-zA-Z0-9_]*)/i);
  if (fromMatch) tables.push(fromMatch[1]);

  const joinMatches = query.match(/JOIN\s+([a-zA-Z_][a-zA-Z0-9_]*)/gi);
  if (joinMatches) {
    joinMatches.forEach(match => {
      const tableName = match.replace(/JOIN\s+/i, '').trim();
      tables.push(tableName);
    });
  }

  // Extraire les colonnes (simplifi├⌐)
  const selectMatch = query.match(/SELECT\s+(.*?)\s+FROM/i);
  if (selectMatch) {
    const selectPart = selectMatch[1];
    if (selectPart !== '*') {
      const cols = selectPart.split(',').map(col => col.trim().split(/\s+/)[0]);
      columns.push(...cols);
    }
  }

  // Estimer la complexit├⌐
  let complexityScore = 0;

  // Op├⌐rations de jointure
  complexityScore += (upperQuery.match(/JOIN/g) || []).length * 2;

  // Sous-requ├¬tes
  complexityScore += (upperQuery.match(/\(.*SELECT.*\)/gi) || []).length * 3;

  // Fonctions d'agr├⌐gation
  complexityScore += (upperQuery.match(/\b(COUNT|SUM|AVG|MIN|MAX|GROUP_CONCAT)\b/g) || []).length;

  // UNION
  complexityScore += (upperQuery.match(/\bUNION\b/g) || []).length * 2;

  // Window functions
  if (upperQuery.match(/\bOVER\s*\(/)) complexityScore += 3;

  // CTE (Common Table Expressions)
  complexityScore += (upperQuery.match(/\bWITH\s+/g) || []).length * 2;

  if (complexityScore >= 6) {
    estimatedComplexity = 'HIGH';
  } else if (complexityScore >= 3) {
    estimatedComplexity = 'MEDIUM';
  }

  return {
    tables: [...new Set(tables)],
    columns: [...new Set(columns)],
    operations: [...new Set(operations)],
    estimatedComplexity
  };
}

// Obtenir le plan d'ex├⌐cution simplifi├⌐ (analyse statique)
export function explainQuery(query: string): {
  steps: string[];
  estimatedCost: number;
  optimizations: string[];
} {
  const steps: string[] = [];
  const optimizations: string[] = [];
  let estimatedCost = 1;

  const upperQuery = query.toUpperCase();

  // Analyser les ├⌐tapes
  if (upperQuery.includes('FROM')) {
    steps.push('Scan des tables sources');
  }

  if (upperQuery.includes('WHERE')) {
    steps.push('Filtrage des lignes (WHERE)');
    estimatedCost += 0.5;
  }

  if (upperQuery.includes('JOIN')) {
    const joinCount = (upperQuery.match(/JOIN/g) || []).length;
    steps.push(`${joinCount} jointure(s)`);
    estimatedCost += joinCount * 2;
  }

  if (upperQuery.includes('GROUP BY')) {
    steps.push('Groupement et agr├⌐gation');
    estimatedCost += 1.5;
  }

  if (upperQuery.includes('ORDER BY')) {
    steps.push('Tri des r├⌐sultats');
    estimatedCost += 1;
  }

  if (upperQuery.includes('DISTINCT')) {
    steps.push('Suppression des doublons');
    estimatedCost += 0.5;
  }

  if (upperQuery.includes('LIMIT')) {
    steps.push('Limitation des r├⌐sultats');
    estimatedCost -= 0.3; // LIMIT r├⌐duit le co├╗t
  }

  // Suggestions d'optimisation
  if (upperQuery.includes('SELECT *')) {
    optimizations.push('├ëvitez SELECT *, sp├⌐cifiez uniquement les colonnes n├⌐cessaires');
  }

  if (upperQuery.includes('WHERE') && !upperQuery.match(/WHERE.*\s+(AND|OR)\s+.*=/)) {
    optimizations.push('Ajoutez des index sur les colonnes utilis├⌐es dans WHERE');
  }

  if (upperQuery.includes('ORDER BY') && !upperQuery.includes('LIMIT')) {
    optimizations.push('Ajoutez LIMIT apr├¿s ORDER BY si vous n\'avez pas besoin de tous les r├⌐sultats');
  }

  if (upperQuery.includes('JOIN') && !upperQuery.includes('ON')) {
    optimizations.push('V├⌐rifiez que les jointures utilisent des index appropri├⌐s');
  }

  if (upperQuery.includes('SUBQUERY') || (query.match(/\(.*SELECT.*\)/))) {
    optimizations.push('Consid├⌐rez convertir les sous-requ├¬tes en JOIN si possible');
  }

  return {
    steps,
    estimatedCost: Math.max(estimatedCost, 0.1),
    optimizations
  };
}
